import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const NoWaitingPeriodBurialInsurance = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            No Waiting Period Burial Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Immediate coverage when you need it most
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Coverage That Starts Right Away
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            Most burial insurance policies have a 2-3 year waiting period for death from illness. Our no waiting period policies provide immediate full coverage for accidental death and can provide accelerated benefits for illness-related deaths.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Policy Waiting Periods Explained
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Accidental Death', desc: 'Full benefit from day one - no waiting' },
            { title: 'Natural Causes (Guaranteed)', desc: '2-3 year waiting period typical' },
            { title: 'Natural Causes (Simplified)', desc: '0-2 years depending on age/health' },
            { title: 'Our Options', desc: 'Choose policies with shorter or no waiting periods' }
          ].map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {item.title}
                  </Typography>
                  <Typography variant="body2">{item.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Why Waiting Periods Exist
          </Typography>
          <Typography variant="body1" paragraph>
            Waiting periods protect insurance companies from anti-selection (people buying insurance right before they expect to die). However, many carriers now offer options with shortened or eliminated waiting periods for upfront full payment or higher premiums.
          </Typography>

          <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
            Our Recommendations:
          </Typography>
          <Stack spacing={2}>
            {[
              'If urgent coverage needed: Simplified Issue policies often have shorter waiting periods',
              'Young/healthy applicants: Can qualify for policies with no waiting period',
              'Accelerated benefits: Some policies provide partial benefits within first 2 years',
              'Full benefit protection: Fixed rates mean coverage remains constant throughout'
            ].map((rec, idx) => (
              <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                <Box sx={{ color: '#FCDC00' }}>✓</Box>
                <Typography>{rec}</Typography>
              </Box>
            ))}
          </Stack>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Immediate Coverage Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default NoWaitingPeriodBurialInsurance;
