import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';
import VerifiedIcon from '@mui/icons-material/Verified';

const BurialInsuranceNoExam = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Burial Insurance No Exam
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Get coverage without the hassle of medical exams
          </Typography>
        </Container>
      </Box>

      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  No Medical Exam Required
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Our no-exam burial insurance policies are designed for those who want quick coverage without the burden of medical testing. Get approved in as little as 24 hours without leaving your home.
                </Typography>
                
                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Advantages of No-Exam Insurance:
                </Typography>
                <Stack spacing={2} sx={{ mb: 4 }}>
                  {[
                    'Quick approval process (24 hours)',
                    'No medical exam or blood work',
                    'Simple application over the phone',
                    'No waiting for lab results',
                    'Guaranteed acceptance available',
                    'Apply from home',
                    'Immediate coverage options'
                  ].map((advantage, idx) => (
                    <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <VerifiedIcon sx={{ color: '#239F7D' }} />
                      <Typography>{advantage}</Typography>
                    </Box>
                  ))}
                </Stack>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Health Conditions Accepted
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  We specialize in providing coverage for those with pre-existing conditions. Whether you have diabetes, heart disease, or cancer, we have options available for you. No medical exam means no rejection based on your health history.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
              fontSize: '1rem',
            }}
          >
            Apply Now - No Exam Required
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BurialInsuranceNoExam;
