import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const BurialInsuranceForMedicaid = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Burial Insurance for Medicaid Recipients
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Protect your family while preserving Medicaid eligibility
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Burial Insurance and Medicaid
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            If you receive Medicaid benefits, you may be concerned about how burial insurance affects your eligibility. Good news: small burial insurance policies are typically exempt from Medicaid resource limits and won't impact your benefits.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Key Information for Medicaid Recipients
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Exempt Resource', desc: 'Burial insurance is typically not counted against asset limits' },
            { title: 'Protects Medicaid', desc: 'Helps protect other assets from Medicaid claims' },
            { title: 'Peace of Mind', desc: 'Funeral costs won\'t burden your family or state' },
            { title: 'Affordable Coverage', desc: 'Small policies with guaranteed acceptance available' }
          ].map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {item.title}
                  </Typography>
                  <Typography variant="body2">{item.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, backgroundColor: '#FFF9E6' }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Important Disclaimer
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>Please consult with your Medicaid caseworker</strong> before purchasing burial insurance to ensure compliance with your state's specific Medicaid rules. Regulations vary by state and individual circumstances.
          </Typography>
        </Card>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Recommended Coverage for Medicaid Recipients
          </Typography>
          <Stack spacing={2}>
            {[
              '• Burial insurance policies of $5,000-$15,000',
              '• Guaranteed acceptance options',
              '• No medical exam required',
              '• Fixed rates for life',
              '• Can be assigned to funeral home if needed',
              '• Generally exempt from Medicaid resource limits'
            ].map((item, idx) => (
              <Typography key={idx}>{item}</Typography>
            ))}
          </Stack>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Medicaid-Friendly Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BurialInsuranceForMedicaid;
