import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const TexasFinalExpense = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Final Expense Insurance in Texas
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Texas-specific burial insurance information and costs
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Average Funeral Costs in Texas
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $7,500 - $11,000
                </Typography>
                <Typography variant="body1" paragraph>
                  Texas offers more affordable funeral costs compared to the national average, making burial insurance more accessible for residents.
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Recommended Coverage
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $12,000 - $20,000
                </Typography>
                <Typography variant="body1" paragraph>
                  Even with lower costs, we recommend adequate coverage for complete financial protection.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Texas Burial Options
          </Typography>
          <Typography variant="body1" paragraph>
            Texas offers both traditional burial and cremation options with reasonable costs. The state has minimal restrictions on funeral practices, giving families flexibility in choosing their preferred arrangements.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Texas Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default TexasFinalExpense;
