import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const Careers = () => {
  const positions = [
    {
      title: 'Insurance Sales Agent',
      location: 'Remote',
      type: 'Full-Time'
    },
    {
      title: 'Customer Service Representative',
      location: 'Virtual',
      type: 'Full-Time'
    },
    {
      title: 'Insurance Advisor',
      location: 'Various Locations',
      type: 'Full-Time'
    }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Careers
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Join our mission to help families
          </Typography>
        </Container>
      </Box>

      {/* About Company */}
      <Container sx={{ py: 6 }}>
        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Work With Aethon Services
        </Typography>
        <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', textAlign: 'center', mb: 6 }}>
          We're growing! Join a team dedicated to helping families protect their financial future with affordable burial insurance solutions.
        </Typography>

        <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 4 }}>
          Open Positions
        </Typography>

        <Grid container spacing={3} sx={{ mb: 6 }}>
          {positions.map((job, idx) => (
            <Grid item xs={12} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Grid container alignItems="center" spacing={2}>
                    <Grid item xs={12} sm={4}>
                      <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                        {job.title}
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={4}>
                      <Typography variant="body2">{job.location}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={4} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', sm: 'flex-end' }, gap: 1 }}>
                      <Button variant="outlined" size="small">
                        View
                      </Button>
                      <Button variant="contained" size="small" sx={{ backgroundColor: '#239F7D' }}>
                        Apply
                      </Button>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* Benefits */}
        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Why Join Us?
          </Typography>
          <ul style={{ paddingLeft: '20px' }}>
            <li><Typography>Competitive compensation and benefits</Typography></li>
            <li><Typography>Remote work opportunities</Typography></li>
            <li><Typography>Comprehensive training and support</Typography></li>
            <li><Typography>Mission-driven work helping families</Typography></li>
            <li><Typography>Professional growth opportunities</Typography></li>
          </ul>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            View All Careers
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default Careers;
