import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const IsBurialInsuranceWorthIt = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Is Burial Insurance Worth It?
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Determining if burial insurance is right for you
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Why You Should Consider It
                </Typography>
                <ul style={{ paddingLeft: '20px' }}>
                  <li><Typography>Protects family from financial burden</Typography></li>
                  <li><Typography>Funeral costs are rising rapidly</Typography></li>
                  <li><Typography>Your family can choose services without financial pressure</Typography></li>
                  <li><Typography>Fixed rates that never increase</Typography></li>
                  <li><Typography>Guaranteed acceptance options available</Typography></li>
                  <li><Typography>Peace of mind knowing you're prepared</Typography></li>
                </ul>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  When It Makes Most Sense
                </Typography>
                <ul style={{ paddingLeft: '20px' }}>
                  <li><Typography>You have little to no savings</Typography></li>
                  <li><Typography>You want your family protected</Typography></li>
                  <li><Typography>You're concerned about medical expenses</Typography></li>
                  <li><Typography>You want to spare your family the cost</Typography></li>
                  <li><Typography>You're in good health to lock in better rates</Typography></li>
                  <li><Typography>You want simplicity and peace of mind</Typography></li>
                </ul>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            The Bottom Line
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            For most people, especially those over 50 or those without substantial savings, burial insurance is absolutely worth it. The average funeral costs $8,000-$12,000, and that can quickly deplete an estate or burden your family.
          </Typography>
          <Typography variant="body1" sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            At just a few dollars per day, burial insurance provides valuable protection and ensures your final wishes are honored without adding financial stress to your family during their time of grief.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Your Free Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default IsBurialInsuranceWorthIt;
