import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const BurialInsuranceForSmokers = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Burial Insurance for Smokers
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Affordable coverage for smokers and tobacco users
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Smokers Can Get Coverage
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            Smoking may increase your rates, but it doesn't disqualify you from burial insurance. Many carriers offer competitive rates for smokers, and we'll help you find the best option available.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          What You Need to Know
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Higher Rates', desc: 'Smokers typically pay 20-50% more than non-smokers' },
            { title: 'Honest Application', desc: 'Be truthful about smoking habits for accurate quotes' },
            { title: 'Still Affordable', desc: 'Even with higher rates, coverage remains budget-friendly' },
            { title: 'Quick Approval', desc: 'No medical exam means fast underwriting' }
          ].map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {item.title}
                  </Typography>
                  <Typography variant="body2">{item.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Sample Rates for Smokers
          </Typography>
          <Stack spacing={2}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', pb: 1, borderBottom: '1px solid #E5E5E5' }}>
              <Typography><strong>Age 50-60</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$80-150/month</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', pb: 1, borderBottom: '1px solid #E5E5E5' }}>
              <Typography><strong>Age 60-70</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$150-250/month</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Age 70-80</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$250-400/month</Typography>
            </Box>
          </Stack>
          <Typography variant="body2" sx={{ mt: 2, color: '#7A7A7A' }}>
            * Rates vary based on age and health. Includes tobacco/cigarette smokers, cigar smokers, and pipe smokers.
          </Typography>
        </Card>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4, backgroundColor: '#FFF9E6' }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Money-Saving Tip
          </Typography>
          <Typography variant="body1">
            Quitting smoking can significantly reduce your rates in the future. Some policies may allow rate reductions if you quit and remain smoke-free for a certain period.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Your Smoker Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BurialInsuranceForSmokers;
