import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Rating } from '@mui/material';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';

const BestBurialInsuranceCompanies = () => {
  const companies = [
    {
      name: 'Aethon Services',
      rating: 5,
      description: 'Leading provider of burial insurance with 24-hour approval',
      features: ['BBB A+ Rating', 'No Medical Exam', '15+ Carriers']
    },
    {
      name: 'InsureCare Plus',
      rating: 4.8,
      description: 'Competitive rates and fast processing',
      features: ['Quick Approval', 'Affordable Rates', 'Expert Advisors']
    },
    {
      name: 'Final Peace Insurance',
      rating: 4.7,
      description: 'Trusted name in final expense insurance',
      features: ['Guaranteed Acceptance', 'Fixed Rates', 'Simple Process']
    }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Best Burial Insurance Companies
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Trusted providers you can rely on
          </Typography>
        </Container>
      </Box>

      {/* Companies Grid */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          {companies.map((company, idx) => (
            <Grid item xs={12} md={4} key={idx}>
              <Card sx={{ boxShadow: 3, height: '100%', position: 'relative' }}>
                {idx === 0 && (
                  <Box sx={{
                    position: 'absolute',
                    top: -15,
                    left: '50%',
                    transform: 'translateX(-50%)',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 1,
                    backgroundColor: '#FCDC00',
                    px: 2,
                    py: 1,
                    borderRadius: 1,
                  }}>
                    <EmojiEventsIcon sx={{ color: '#000' }} />
                    <Typography sx={{ fontWeight: 'bold', color: '#000' }}>Top Rated</Typography>
                  </Box>
                )}
                <CardContent sx={{ p: 4 }}>
                  <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 1 }}>
                    {company.name}
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 2, gap: 1 }}>
                    <Rating value={company.rating} readOnly precision={0.1} />
                    <Typography sx={{ color: '#7A7A7A' }}>{company.rating}</Typography>
                  </Box>
                  <Typography variant="body1" paragraph sx={{ fontSize: '1rem', mb: 3 }}>
                    {company.description}
                  </Typography>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2, color: '#239F7D' }}>
                    Why Choose Them:
                  </Typography>
                  <ul style={{ paddingLeft: '20px' }}>
                    {company.features.map((feature, i) => (
                      <li key={i}><Typography>{feature}</Typography></li>
                    ))}
                  </ul>
                  <Button
                    variant="contained"
                    fullWidth
                    sx={{
                      backgroundColor: '#0170B9',
                      color: '#FFFFFF',
                      fontWeight: 'bold',
                      mt: 3,
                    }}
                  >
                    Get Quote
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3 }}>
            Compare Plans and Save
          </Typography>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Compare All Plans
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BestBurialInsuranceCompanies;
