import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const Blog = () => {
  const blogPosts = [
    {
      title: 'Understanding Final Expense Insurance',
      date: 'December 10, 2024',
      excerpt: 'Learn what final expense insurance is and why it matters for your family...'
    },
    {
      title: 'How to Choose the Right Coverage Amount',
      date: 'December 5, 2024',
      excerpt: 'Determining the right burial insurance coverage for your specific situation...'
    },
    {
      title: 'Funeral Costs Are Rising - Is Your Family Protected?',
      date: 'November 28, 2024',
      excerpt: 'Recent data shows funeral costs continue to increase year over year...'
    }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Blog
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Insights and information about burial insurance
          </Typography>
        </Container>
      </Box>

      {/* Blog Posts */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          {blogPosts.map((post, idx) => (
            <Grid item xs={12} md={6} lg={4} key={idx}>
              <Card sx={{ boxShadow: 3, cursor: 'pointer', '&:hover': { boxShadow: 5 } }}>
                <CardContent sx={{ p: 4 }}>
                  <Typography variant="caption" sx={{ color: '#7A7A7A' }}>
                    {post.date}
                  </Typography>
                  <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 2, color: '#0170B9' }}>
                    {post.title}
                  </Typography>
                  <Typography variant="body2" paragraph>
                    {post.excerpt}
                  </Typography>
                  <Button
                    variant="text"
                    sx={{ color: '#239F7D', fontWeight: 'bold' }}
                  >
                    Read More →
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default Blog;
