import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const HowMuchBurialInsuranceCost = () => {
  const examples = [
    { age: '50-60', guaranteed: '$75-120/mo', simplified: '$50-85/mo', coverage: '$10K-25K' },
    { age: '60-70', guaranteed: '$120-200/mo', simplified: '$85-145/mo', coverage: '$15K-35K' },
    { age: '70-80', guaranteed: '$200-300/mo', simplified: '$150-220/mo', coverage: '$20K-50K' },
    { age: '80+', guaranteed: '$300+/mo', simplified: '$220+/mo', coverage: '$25K-50K' }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            How Much Does Burial Insurance Cost?
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Transparent pricing with no hidden fees
          </Typography>
        </Container>
      </Box>

      {/* Cost Examples */}
      <Container sx={{ py: 6 }}>
        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Sample Monthly Costs by Age
        </Typography>

        <Grid container spacing={2} sx={{ mb: 4 }}>
          {examples.map((ex, idx) => (
            <Grid item xs={12} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={12} sm={3}>
                      <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                        Ages {ex.age}
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        <strong>Guaranteed:</strong> {ex.guaranteed}
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        <strong>Simplified:</strong> {ex.simplified}
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        <strong>Coverage:</strong> {ex.coverage}
                      </Typography>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 2, color: '#0170B9' }}>
            Important Notes:
          </Typography>
          <Typography variant="body1" paragraph>
            • Prices are estimates based on age and health status
          </Typography>
          <Typography variant="body1" paragraph>
            • Exact rates depend on your individual underwriting
          </Typography>
          <Typography variant="body1" paragraph>
            • Rates are locked in and never increase
          </Typography>
          <Typography variant="body1" paragraph>
            • No medical exam required for most policies
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            See Your Personal Rate
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default HowMuchBurialInsuranceCost;
