import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const BurialInsuranceForDiabetics = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Burial Insurance for Diabetics
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Affordable coverage for those with diabetes
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Diabetes Doesn't Disqualify You
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            With millions of Americans managing diabetes, we've designed insurance policies specifically for diabetics. Whether you have Type 1 or Type 2 diabetes, we have options that work for your situation.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          What We Need to Know
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { question: 'Type of Diabetes?', info: 'Tell us if you have Type 1 or Type 2' },
            { question: 'How Long?', info: 'How long have you had diabetes?' },
            { question: 'Management', info: 'Are you managing it with medication?' },
            { question: 'Complications?', info: 'Any related health complications?' }
          ].map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {item.question}
                  </Typography>
                  <Typography variant="body2">{item.info}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Coverage Available
          </Typography>
          <Stack spacing={2}>
            {[
              'Guaranteed Acceptance: Available regardless of blood sugar control',
              'Simplified Issue: Approved based on brief health questions',
              'Coverage Amounts: $5,000 to $50,000',
              'Fixed Monthly Rates: Never increase over time',
              'Quick Processing: Approved within 24 hours',
              'Easy Application: Phone or online application'
            ].map((item, idx) => (
              <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                <Box sx={{ color: '#FCDC00' }}>✓</Box>
                <Typography>{item}</Typography>
              </Box>
            ))}
          </Stack>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Quote for Diabetics
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BurialInsuranceForDiabetics;
