import React from 'react';
import {
  Box,
  Container,
  Typography,
  Grid,
  Card,
  Stack,
} from '@mui/material';
import BadgeIcon from '@mui/icons-material/Badge';
import GroupsIcon from '@mui/icons-material/Groups';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import HandshakeIcon from '@mui/icons-material/Handshake';

const About = () => {
  const values = [
    {
      icon: <BadgeIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Integrity',
      description: 'We operate with honesty and transparency in all our dealings.',
    },
    {
      icon: <GroupsIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Customer First',
      description: 'Your needs and satisfaction are our top priorities.',
    },
    {
      icon: <EmojiEventsIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Excellence',
      description: 'We strive for excellence in every service we provide.',
    },
    {
      icon: <HandshakeIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Partnership',
      description: 'We work with you as partners to find the best solutions.',
    },
  ];

  const achievements = [
    {
      number: '15+',
      label: 'Insurance Carriers',
    },
    {
      number: '10,000+',
      label: 'Happy Customers',
    },
    {
      number: 'A+',
      label: 'BBB Rating',
    },
    {
      number: '24hrs',
      label: 'Quick Approval',
    },
  ];

  return (
    <Box sx={{ minHeight: '100vh' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #319f7e 100%)',
          color: '#FFFFFF',
          py: 8,
          position: 'relative',
        }}
      >
        <Container maxWidth="lg">
          <Typography variant="h1" sx={{ mb: 2 }}>
            About Senior Life Services
          </Typography>
          <Typography variant="body1" sx={{ fontSize: '1.2rem', maxWidth: '600px' }}>
            Dedicated to providing affordable and accessible burial insurance coverage to families throughout Florida.
          </Typography>
        </Container>
      </Box>

      {/* Our Story Section */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Grid container spacing={6} alignItems="center">
          <Grid item xs={12} md={6}>
            <Box
              sx={{
                background: 'linear-gradient(135deg, #239F7D 0%, #006F51 100%)',
                borderRadius: '20px',
                p: 4,
                color: '#FFFFFF',
                minHeight: '300px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <Typography sx={{ fontSize: '2rem', fontWeight: 'bold', opacity: 0.7 }}>
                [Image Placeholder]
              </Typography>
            </Box>
          </Grid>
          <Grid item xs={12} md={6}>
            <Typography
              variant="h2"
              sx={{
                mb: 2,
                color: '#239F7D',
              }}
            >
              Our Story
            </Typography>
            <Typography
              variant="body1"
              sx={{
                mb: 2,
                color: '#7A7A7A',
                lineHeight: 1.8,
              }}
            >
              Senior Life Services was founded with a simple mission: to make affordable burial insurance accessible to everyone. For years, families struggled to find coverage that was both affordable and easy to understand.
            </Typography>
            <Typography
              variant="body1"
              sx={{
                mb: 2,
                color: '#7A7A7A',
                lineHeight: 1.8,
              }}
            >
              Our team of dedicated professionals recognized this gap in the market and decided to take action. We partnered with leading insurance carriers to offer competitive rates and flexible coverage options.
            </Typography>
            <Typography
              variant="body1"
              sx={{
                color: '#7A7A7A',
                lineHeight: 1.8,
              }}
            >
              Today, we're proud to serve thousands of happy customers who have found peace of mind knowing their families are protected with affordable burial insurance coverage.
            </Typography>
          </Grid>
        </Grid>
      </Container>

      {/* Achievements Section */}
      <Box sx={{ backgroundColor: '#F9F9F9', py: 8 }}>
        <Container maxWidth="lg">
          <Typography
            variant="h2"
            sx={{
              textAlign: 'center',
              mb: 8,
              color: '#3D4459',
            }}
          >
            Our Achievements
          </Typography>

          <Grid container spacing={4}>
            {achievements.map((achievement, index) => (
              <Grid item xs={12} sm={6} md={3} key={index}>
                <Card
                  sx={{
                    textAlign: 'center',
                    p: 4,
                    backgroundColor: '#FFFFFF',
                    border: '2px solid #239F7D',
                  }}
                >
                  <Typography
                    variant="h3"
                    sx={{
                      fontWeight: 'bold',
                      color: '#239F7D',
                      mb: 1,
                    }}
                  >
                    {achievement.number}
                  </Typography>
                  <Typography
                    variant="body1"
                    sx={{
                      color: '#4B4F58',
                      fontWeight: 'bold',
                    }}
                  >
                    {achievement.label}
                  </Typography>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      {/* Our Values Section */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Typography
          variant="h2"
          sx={{
            textAlign: 'center',
            mb: 6,
            color: '#239F7D',
          }}
        >
          Our Core Values
        </Typography>

        <Grid container spacing={4}>
          {values.map((value, index) => (
            <Grid item xs={12} sm={6} md={3} key={index}>
              <Card
                sx={{
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  p: 3,
                  textAlign: 'center',
                  backgroundColor: '#FFFFFF',
                  border: '1px solid #E5E5E5',
                }}
              >
                <Box sx={{ mb: 2 }}>
                  {value.icon}
                </Box>
                <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold', color: '#006F51' }}>
                  {value.title}
                </Typography>
                <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                  {value.description}
                </Typography>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>

      {/* Team Section */}
      <Box sx={{ backgroundColor: '#F9F9F9', py: 8 }}>
        <Container maxWidth="lg">
          <Typography
            variant="h2"
            sx={{
              textAlign: 'center',
              mb: 6,
              color: '#3D4459',
            }}
          >
            Our Team
          </Typography>
          <Typography
            variant="body1"
            sx={{
              textAlign: 'center',
              mb: 6,
              color: '#7A7A7A',
              maxWidth: '600px',
              mx: 'auto',
            }}
          >
            Our team consists of experienced insurance professionals dedicated to helping you find the perfect coverage for your family's needs.
          </Typography>

          <Grid container spacing={4}>
            {[1, 2, 3, 4].map((member, index) => (
              <Grid item xs={12} sm={6} md={3} key={index}>
                <Card
                  sx={{
                    textAlign: 'center',
                    overflow: 'hidden',
                    backgroundColor: '#FFFFFF',
                  }}
                >
                  <Box
                    sx={{
                      background: 'linear-gradient(135deg, #239F7D 0%, #006F51 100%)',
                      height: '200px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: '#FFFFFF',
                    }}
                  >
                    <Typography sx={{ fontSize: '3rem', opacity: 0.7 }}>
                      👤
                    </Typography>
                  </Box>
                  <Box sx={{ p: 2 }}>
                    <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 0.5 }}>
                      Team Member {index + 1}
                    </Typography>
                    <Typography variant="body2" sx={{ color: '#239F7D', mb: 1 }}>
                      Licensed Agent
                    </Typography>
                    <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                      With years of experience helping families find affordable coverage.
                    </Typography>
                  </Box>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      {/* Why Choose Us Section */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Typography
          variant="h2"
          sx={{
            mb: 6,
            color: '#239F7D',
          }}
        >
          Why Choose Senior Life Services?
        </Typography>

        <Stack spacing={3}>
          {[
            'Over 10,000 satisfied customers across Florida',
            'Partnership with 15+ leading insurance carriers',
            'A+ Rating from the Better Business Bureau',
            'Licensed and experienced insurance professionals',
            'Quick approval process - often same day',
            'No waiting period plans available',
            'Competitive rates and flexible coverage options',
            'Dedicated customer support and service',
          ].map((reason, index) => (
            <Box key={index} sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
              <Box
                sx={{
                  width: 30,
                  height: 30,
                  borderRadius: '50%',
                  backgroundColor: '#239F7D',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#FFFFFF',
                  fontWeight: 'bold',
                  flexShrink: 0,
                  mt: 0.5,
                }}
              >
                ✓
              </Box>
              <Typography variant="body1" sx={{ color: '#4B4F58' }}>
                {reason}
              </Typography>
            </Box>
          ))}
        </Stack>
      </Container>
    </Box>
  );
};

export default About;
