import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const HighRiskLifeInsurance = () => {
  const conditions = [
    { name: 'Cancer Patients', link: '/high-risk/cancer' },
    { name: 'Diabetics', link: '/high-risk/diabetics' },
    { name: 'Seniors Over 80', link: '/high-risk/seniors-over-80' },
    { name: 'Medicaid Recipients', link: '/high-risk/medicaid' },
    { name: 'No Waiting Period', link: '/high-risk/no-waiting-period' },
    { name: 'Smokers', link: '/high-risk/smokers' }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            High-Risk Life Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Coverage for those who are hard to insure
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            What is High-Risk Life Insurance?
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            High-risk life insurance is specifically designed for individuals with serious health conditions, disabilities, or other factors that make them difficult to insure through traditional channels. We specialize in finding coverage for those who've been rejected elsewhere.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          High-Risk Coverage We Offer
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {conditions.map((condition, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2, cursor: 'pointer', '&:hover': { boxShadow: 4 } }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 2 }}>
                    {condition.name}
                  </Typography>
                  <Button
                    variant="outlined"
                    size="small"
                    sx={{ borderColor: '#0170B9', color: '#0170B9' }}
                  >
                    Learn More
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Our Commitment
          </Typography>
          <Typography variant="body1" paragraph>
            We believe everyone deserves access to life insurance. No matter your health situation, our team will work with you to find a policy that fits your needs and budget.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Your High-Risk Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default HighRiskLifeInsurance;
