import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const GivingBack = () => {
  const initiatives = [
    {
      title: 'Community Support',
      description: 'Supporting local charities and community programs'
    },
    {
      title: 'Education Grants',
      description: 'Providing scholarships to deserving students'
    },
    {
      title: 'Healthcare Initiatives',
      description: 'Supporting medical research and healthcare access'
    },
    {
      title: 'Senior Services',
      description: 'Helping seniors access essential services and support'
    }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Giving Back
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Our commitment to community
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Making a Difference
        </Typography>
        <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', textAlign: 'center', mb: 6 }}>
          Aethon Services believes in giving back to the communities we serve. Through charitable partnerships and community initiatives, we're committed to making a positive impact.
        </Typography>

        <Grid container spacing={3} sx={{ mb: 6 }}>
          {initiatives.map((init, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2, height: '100%' }}>
                <CardContent sx={{ p: 4, textAlign: 'center' }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 2 }}>
                    {init.title}
                  </Typography>
                  <Typography variant="body2">{init.description}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* Featured Initiative */}
        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Featured Initiative
          </Typography>
          <Typography variant="body1" paragraph>
            This year, Aethon Services has committed $500,000 to support senior care initiatives and burial assistance programs for those in financial need.
          </Typography>
          <Typography variant="body1">
            Together with our partners, we're working to ensure that every family can afford a dignified funeral, regardless of their financial circumstances.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Support Our Mission
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default GivingBack;
