import React, { useState } from 'react';
import {
  Box,
  Container,
  Typography,
  Button,
  Grid,
  TextField,
  Stack,
  Paper,
} from '@mui/material';
import PhoneIcon from '@mui/icons-material/Phone';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import EmailIcon from '@mui/icons-material/Email';
import AccessTimeIcon from '@mui/icons-material/AccessTime';

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    // Handle form submission
  };

  return (
    <Box sx={{ minHeight: '100vh' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #319f7e 100%)',
          color: '#FFFFFF',
          py: 8,
          position: 'relative',
        }}
      >
        <Container maxWidth="lg">
          <Typography variant="h1" sx={{ mb: 2 }}>
            Contact Us
          </Typography>
          <Typography variant="body1" sx={{ fontSize: '1.2rem', maxWidth: '600px' }}>
            Have questions? Our team of licensed agents is ready to help you find the perfect insurance coverage.
          </Typography>
        </Container>
      </Box>

      {/* Contact Info Cards */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Grid container spacing={3} sx={{ mb: 8 }}>
          {/* Phone */}
          <Grid item xs={12} sm={6} md={3}>
            <Paper
              sx={{
                p: 3,
                textAlign: 'center',
                backgroundColor: '#FFFFFF',
                border: '1px solid #E5E5E5',
              }}
            >
              <PhoneIcon
                sx={{
                  fontSize: 50,
                  color: '#239F7D',
                  mb: 2,
                }}
              />
              <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                Phone
              </Typography>
              <Typography
                variant="body2"
                sx={{
                  color: '#0170B9',
                  fontSize: '1.1rem',
                }}
              >
                (800) 548-3249
              </Typography>
            </Paper>
          </Grid>

          {/* Email */}
          <Grid item xs={12} sm={6} md={3}>
            <Paper
              sx={{
                p: 3,
                textAlign: 'center',
                backgroundColor: '#FFFFFF',
                border: '1px solid #E5E5E5',
              }}
            >
              <EmailIcon
                sx={{
                  fontSize: 50,
                  color: '#239F7D',
                  mb: 2,
                }}
              />
              <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                Email
              </Typography>
              <Typography
                variant="body2"
                sx={{
                  color: '#0170B9',
                }}
              >
                info@seniorlifeservices.com
              </Typography>
            </Paper>
          </Grid>

          {/* Address */}
          <Grid item xs={12} sm={6} md={3}>
            <Paper
              sx={{
                p: 3,
                textAlign: 'center',
                backgroundColor: '#FFFFFF',
                border: '1px solid #E5E5E5',
              }}
            >
              <LocationOnIcon
                sx={{
                  fontSize: 50,
                  color: '#239F7D',
                  mb: 2,
                }}
              />
              <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                Address
              </Typography>
              <Typography variant="body2" sx={{ color: '#4B4F58' }}>
                2300 3rd Ct
                <br />
                Vero Beach, FL 32960
              </Typography>
            </Paper>
          </Grid>

          {/* Hours */}
          <Grid item xs={12} sm={6} md={3}>
            <Paper
              sx={{
                p: 3,
                textAlign: 'center',
                backgroundColor: '#FFFFFF',
                border: '1px solid #E5E5E5',
              }}
            >
              <AccessTimeIcon
                sx={{
                  fontSize: 50,
                  color: '#239F7D',
                  mb: 2,
                }}
              />
              <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                Hours
              </Typography>
              <Typography variant="body2" sx={{ color: '#4B4F58' }}>
                Mon - Fri: 8am - 5pm
                <br />
                Sat: 10am - 3pm
                <br />
                Sun: Closed
              </Typography>
            </Paper>
          </Grid>
        </Grid>
      </Container>

      {/* Contact Form Section */}
      <Box sx={{ backgroundColor: '#F9F9F9', py: 8 }}>
        <Container maxWidth="lg">
          <Grid container spacing={6}>
            {/* Form */}
            <Grid item xs={12} md={6}>
              <Typography variant="h2" sx={{ mb: 3, color: '#239F7D' }}>
                Send us a Message
              </Typography>
              <Box component="form" onSubmit={handleSubmit}>
                <Stack spacing={2}>
                  <TextField
                    fullWidth
                    label="Name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    required
                    variant="outlined"
                  />
                  <TextField
                    fullWidth
                    label="Email"
                    name="email"
                    type="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    variant="outlined"
                  />
                  <TextField
                    fullWidth
                    label="Phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    variant="outlined"
                  />
                  <TextField
                    fullWidth
                    label="Message"
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    required
                    multiline
                    rows={4}
                    variant="outlined"
                  />
                  <Button
                    type="submit"
                    variant="contained"
                    sx={{
                      backgroundColor: '#239F7D',
                      py: 1.5,
                      fontSize: '1rem',
                      '&:hover': {
                        backgroundColor: '#006F51',
                      },
                    }}
                  >
                    Send Message
                  </Button>
                </Stack>
              </Box>
            </Grid>

            {/* Map or Additional Info */}
            <Grid item xs={12} md={6}>
              <Box
                sx={{
                  backgroundColor: '#FFFFFF',
                  borderRadius: '15px',
                  p: 4,
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'center',
                  boxShadow: '0px 0px 20px rgba(0, 0, 0, 0.05)',
                }}
              >
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 2 }}>
                  Why Work With Us?
                </Typography>
                <Stack spacing={2}>
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Box
                      sx={{
                        width: 40,
                        height: 40,
                        borderRadius: '50%',
                        backgroundColor: '#239F7D',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#FFFFFF',
                        fontWeight: 'bold',
                        flexShrink: 0,
                      }}
                    >
                      1
                    </Box>
                    <Box>
                      <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                        Expert Guidance
                      </Typography>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        Our licensed agents have years of experience helping families.
                      </Typography>
                    </Box>
                  </Box>
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Box
                      sx={{
                        width: 40,
                        height: 40,
                        borderRadius: '50%',
                        backgroundColor: '#239F7D',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#FFFFFF',
                        fontWeight: 'bold',
                        flexShrink: 0,
                      }}
                    >
                      2
                    </Box>
                    <Box>
                      <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                        Fast Processing
                      </Typography>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        Get approved in as little as 24-48 hours.
                      </Typography>
                    </Box>
                  </Box>
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Box
                      sx={{
                        width: 40,
                        height: 40,
                        borderRadius: '50%',
                        backgroundColor: '#239F7D',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#FFFFFF',
                        fontWeight: 'bold',
                        flexShrink: 0,
                      }}
                    >
                      3
                    </Box>
                    <Box>
                      <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                        Competitive Rates
                      </Typography>
                      <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                        We compare rates from 15+ carriers to save you money.
                      </Typography>
                    </Box>
                  </Box>
                </Stack>
              </Box>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </Box>
  );
};

export default Contact;
