import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const CostOfBurialInsurance = () => {
  const costFactors = [
    { factor: 'Age', impact: 'Primary factor affecting rates' },
    { factor: 'Health Status', impact: 'Pre-existing conditions may increase cost' },
    { factor: 'Coverage Amount', impact: 'Higher coverage = higher premiums' },
    { factor: 'Type of Policy', impact: 'Guaranteed vs. Simplified Issue varies' },
    { factor: 'Smoker Status', impact: 'Smokers typically pay more' },
    { factor: 'Gender', impact: 'May affect pricing' }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            The Cost of Burial Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Affordable coverage for every budget
          </Typography>
        </Container>
      </Box>

      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Understanding Burial Insurance Costs
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  The cost of burial insurance varies based on several factors. Most burial insurance policies range from $50 to $300+ per month depending on your age, health status, and coverage amount. We offer affordable options to fit any budget.
                </Typography>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 3, color: '#239F7D' }}>
                  Factors That Affect Your Cost:
                </Typography>
                <Grid container spacing={2} sx={{ mb: 4 }}>
                  {costFactors.map((item, idx) => (
                    <Grid item xs={12} sm={6} key={idx}>
                      <Card sx={{ backgroundColor: '#F5F5F5' }}>
                        <CardContent>
                          <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                            {item.factor}
                          </Typography>
                          <Typography variant="body2">{item.impact}</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  ))}
                </Grid>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Money-Saving Tips:
                </Typography>
                <Stack spacing={2}>
                  {[
                    'Compare quotes from multiple carriers',
                    'Choose the right coverage amount for your needs',
                    'Apply early while you\'re in good health',
                    'Ask about discounts for spouses or groups',
                    'Review your policy annually'
                  ].map((tip, idx) => (
                    <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00', fontSize: '1.5rem' }}>💡</Box>
                      <Typography>{tip}</Typography>
                    </Box>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Free Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default CostOfBurialInsurance;
