import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';

const WhatIsBurialInsurance = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            What is Burial Insurance?
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Understand the basics of burial insurance and why it matters
          </Typography>
        </Container>
      </Box>

      {/* Main Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Understanding Burial Insurance
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Burial insurance, also known as final expense insurance, is a type of whole life insurance designed to help cover the costs associated with your funeral and burial arrangements. It provides your family with funds to pay for services such as caskets, embalming, cremation, flowers, and other final expense costs.
                </Typography>
                
                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Key Benefits:
                </Typography>
                <Stack spacing={2} sx={{ mb: 4 }}>
                  {[
                    'Guaranteed acceptance for most applicants',
                    'No medical exam required',
                    'Fixed rates that never increase',
                    'Coverage up to $50,000',
                    'Quick approval process (24 hours or less)',
                    'Immediate death benefit availability'
                  ].map((benefit, idx) => (
                    <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00', fontSize: '1.5rem' }}>✓</Box>
                      <Typography>{benefit}</Typography>
                    </Box>
                  ))}
                </Stack>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Why Choose Burial Insurance?
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Burial insurance protects your family from unexpected costs and provides peace of mind. Unlike traditional life insurance, burial insurance focuses specifically on end-of-life expenses, making it an affordable option for seniors and those on a budget.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* CTA Section */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3 }}>
            Ready to Protect Your Family?
          </Typography>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
              fontSize: '1rem',
              '&:hover': {
                backgroundColor: '#E6C800',
              },
            }}
            endIcon={<ArrowForwardIcon />}
          >
            Get a Free Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default WhatIsBurialInsurance;
