import React from 'react';
import {
  Box,
  Container,
  Typography,
  Button,
  Grid,
  Card,
  CardContent,
  Stack,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import SpeedIcon from '@mui/icons-material/Speed';
import VerifiedIcon from '@mui/icons-material/Verified';
import PeopleIcon from '@mui/icons-material/People';
import LightbulbIcon from '@mui/icons-material/Lightbulb';

const BurialInsurance = () => {
  const benefits = [
    {
      icon: <SpeedIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Quick Approval',
      description: 'Get approved for burial insurance in as little as 24 hours.',
    },
    {
      icon: <VerifiedIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'No Medical Exam',
      description: 'Many plans available without requiring a medical examination.',
    },
    {
      icon: <PeopleIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Coverage Up to $50,000',
      description: 'Generous coverage limits to ensure your family is protected.',
    },
    {
      icon: <LightbulbIcon sx={{ fontSize: 60, color: '#239F7D' }} />,
      title: 'Fixed Rates',
      description: 'Your rates never increase - guaranteed for life.',
    },
  ];

  const coverageOptions = [
    {
      title: 'Basic Plan',
      price: '$99',
      period: '/month',
      coverage: '$10,000',
      features: [
        'Coverage up to $10,000',
        '5-year guaranteed period',
        'Quick approval',
        'No waiting period*',
        'Funeral cost assistance',
      ],
    },
    {
      title: 'Standard Plan',
      price: '$149',
      period: '/month',
      coverage: '$25,000',
      featured: true,
      features: [
        'Coverage up to $25,000',
        'Lifetime coverage',
        'Quick approval',
        'No waiting period*',
        'Funeral cost assistance',
        'Family support',
      ],
    },
    {
      title: 'Premium Plan',
      price: '$199',
      period: '/month',
      coverage: '$50,000',
      features: [
        'Coverage up to $50,000',
        'Lifetime coverage',
        'Priority processing',
        'No waiting period*',
        'Full funeral coverage',
        'Estate planning assistance',
      ],
    },
  ];

  return (
    <Box sx={{ minHeight: '100vh' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #319f7e 100%)',
          color: '#FFFFFF',
          py: 8,
          position: 'relative',
        }}
      >
        <Container maxWidth="lg">
          <Typography variant="h1" sx={{ mb: 2 }}>
            Burial Insurance Plans
          </Typography>
          <Typography variant="body1" sx={{ fontSize: '1.2rem', maxWidth: '600px' }}>
            Protect your loved ones with affordable burial insurance coverage. No waiting period, no medical exam required.
          </Typography>
        </Container>
      </Box>

      {/* Benefits Section */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Typography
          variant="h2"
          sx={{
            textAlign: 'center',
            mb: 6,
            color: '#239F7D',
          }}
        >
          Why Choose Senior Life Services?
        </Typography>

        <Grid container spacing={4}>
          {benefits.map((benefit, index) => (
            <Grid item xs={12} sm={6} md={3} key={index}>
              <Card
                sx={{
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  p: 3,
                  textAlign: 'center',
                  backgroundColor: '#FFFFFF',
                  border: '1px solid #E5E5E5',
                }}
              >
                <Box sx={{ mb: 2 }}>
                  {benefit.icon}
                </Box>
                <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold', color: '#006F51' }}>
                  {benefit.title}
                </Typography>
                <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                  {benefit.description}
                </Typography>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>

      {/* Coverage Plans */}
      <Box sx={{ backgroundColor: '#F9F9F9', py: 8 }}>
        <Container maxWidth="lg">
          <Typography
            variant="h2"
            sx={{
              textAlign: 'center',
              mb: 6,
              color: '#3D4459',
            }}
          >
            Our Coverage Plans
          </Typography>

          <Grid container spacing={3}>
            {coverageOptions.map((plan, index) => (
              <Grid item xs={12} md={4} key={index}>
                <Card
                  sx={{
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    p: 3,
                    position: 'relative',
                    border: plan.featured ? '3px solid #239F7D' : '1px solid #E5E5E5',
                    transform: plan.featured ? 'scale(1.05)' : 'scale(1)',
                    transition: 'all 0.3s ease',
                  }}
                >
                  {plan.featured && (
                    <Box
                      sx={{
                        position: 'absolute',
                        top: -15,
                        left: '50%',
                        transform: 'translateX(-50%)',
                        backgroundColor: '#239F7D',
                        color: '#FFFFFF',
                        px: 2,
                        py: 0.5,
                        borderRadius: '20px',
                        fontSize: '0.85rem',
                        fontWeight: 'bold',
                      }}
                    >
                      Most Popular
                    </Box>
                  )}
                  <Typography
                    variant="h5"
                    sx={{ fontWeight: 'bold', mb: 1, color: '#3D4459' }}
                  >
                    {plan.title}
                  </Typography>
                  <Box sx={{ mb: 3 }}>
                    <Typography
                      variant="h3"
                      sx={{
                        fontWeight: 'bold',
                        color: plan.featured ? '#239F7D' : '#0170B9',
                      }}
                    >
                      {plan.price}
                      <Typography component="span" sx={{ fontSize: '1rem' }}>
                        {plan.period}
                      </Typography>
                    </Typography>
                    <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                      Coverage: {plan.coverage}
                    </Typography>
                  </Box>
                  <Stack spacing={1} sx={{ mb: 3, flex: 1 }}>
                    {plan.features.map((feature, idx) => (
                      <Box
                        key={idx}
                        sx={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: 1,
                        }}
                      >
                        <VerifiedIcon sx={{ color: '#239F7D', fontSize: '1.2rem' }} />
                        <Typography variant="body2" sx={{ color: '#4B4F58' }}>
                          {feature}
                        </Typography>
                      </Box>
                    ))}
                  </Stack>
                  <Button
                    variant="contained"
                    fullWidth
                    endIcon={<ArrowForwardIcon />}
                    sx={{
                      backgroundColor: plan.featured ? '#239F7D' : '#0170B9',
                      '&:hover': {
                        backgroundColor: plan.featured ? '#006F51' : '#00508F',
                      },
                    }}
                  >
                    Select Plan
                  </Button>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      {/* Who Qualifies */}
      <Container maxWidth="lg" sx={{ py: 8 }}>
        <Grid container spacing={4} alignItems="center">
          <Grid item xs={12} md={6}>
            <Typography
              variant="h2"
              sx={{
                mb: 2,
                color: '#239F7D',
              }}
            >
              Who Can Qualify?
            </Typography>
            <Typography
              variant="body1"
              sx={{
                mb: 3,
                color: '#7A7A7A',
              }}
            >
              Burial insurance is designed for people of all ages and health conditions. We work with seniors and families to find affordable coverage.
            </Typography>
            <Stack spacing={2}>
              <Box sx={{ display: 'flex', gap: 2 }}>
                <VerifiedIcon sx={{ color: '#239F7D', mt: 0.5 }} />
                <Box>
                  <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: '#3D4459' }}>
                    Ages 45-85
                  </Typography>
                  <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                    Coverage available for adults in this age range.
                  </Typography>
                </Box>
              </Box>
              <Box sx={{ display: 'flex', gap: 2 }}>
                <VerifiedIcon sx={{ color: '#239F7D', mt: 0.5 }} />
                <Box>
                  <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: '#3D4459' }}>
                    All Health Conditions
                  </Typography>
                  <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                    No medical exam required for most plans.
                  </Typography>
                </Box>
              </Box>
              <Box sx={{ display: 'flex', gap: 2 }}>
                <VerifiedIcon sx={{ color: '#239F7D', mt: 0.5 }} />
                <Box>
                  <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: '#3D4459' }}>
                    Quick Approval
                  </Typography>
                  <Typography variant="body2" sx={{ color: '#7A7A7A' }}>
                    Get approved within 24-48 hours.
                  </Typography>
                </Box>
              </Box>
            </Stack>
          </Grid>
          <Grid item xs={12} md={6}>
            <Box
              sx={{
                background: 'linear-gradient(135deg, #239F7D 0%, #006F51 100%)',
                borderRadius: '20px',
                p: 4,
                color: '#FFFFFF',
                textAlign: 'center',
              }}
            >
              <Typography variant="h5" sx={{ mb: 2, fontWeight: 'bold' }}>
                Ready to Get Started?
              </Typography>
              <Typography variant="body1" sx={{ mb: 4 }}>
                Call our team of licensed agents today for a free quote.
              </Typography>
              <Button
                variant="contained"
                sx={{
                  backgroundColor: '#FCDC00',
                  color: '#000',
                  '&:hover': {
                    backgroundColor: '#E6C800',
                  },
                }}
              >
                Call (800) 548-3249
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default BurialInsurance;
