import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const SimplifiedIssueBurialInsurance = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Simplified Issue Life Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Quick approval with minimal underwriting
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  How Simplified Issue Works
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Simplified issue life insurance uses a streamlined application process where you answer health questions instead of undergoing a medical exam. This means faster approval without the inconvenience of lab tests or doctor visits.
                </Typography>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Features:
                </Typography>
                <Stack spacing={2} sx={{ mb: 4 }}>
                  {[
                    'Answer health questions on application',
                    'No medical exam required',
                    'Coverage up to $50,000',
                    'Fixed rates for life',
                    'Approval in 24-48 hours',
                    'Rates based on age and health'
                  ].map((feature, idx) => (
                    <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00', fontSize: '1.5rem' }}>✓</Box>
                      <Typography>{feature}</Typography>
                    </Box>
                  ))}
                </Stack>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Who Qualifies?
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Most people ages 50-85 can qualify for simplified issue life insurance. Your answers to health questions determine your eligibility and rates. We work with you to find the best option available.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Simplified Quote Today
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default SimplifiedIssueBurialInsurance;
