import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const AverageFuneralCost = () => {
  const funeralCosts = [
    { item: 'Casket', cost: '$1,000 - $3,500' },
    { item: 'Embalming', cost: '$500 - $750' },
    { item: 'Viewing & Visitation', cost: '$300 - $800' },
    { item: 'Funeral Service', cost: '$500 - $2,500' },
    { item: 'Hearse & Transport', cost: '$300 - $500' },
    { item: 'Cemetery Plot', cost: '$500 - $3,000' },
    { item: 'Grave Opening & Closing', cost: '$800 - $1,500' },
    { item: 'Headstone', cost: '$1,000 - $3,000' },
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Average Funeral Cost
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Understanding final expense costs
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4, backgroundColor: '#F5F5F5' }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 2 }}>
            National Average: $8,000 - $12,000
          </Typography>
          <Typography variant="body1">
            The average funeral costs have continued to rise. A typical funeral service now costs between $8,000 and $12,000 when including all associated expenses.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3 }}>
          Breakdown of Typical Funeral Expenses
        </Typography>

        <Grid container spacing={2} sx={{ mb: 4 }}>
          {funeralCosts.map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9' }}>
                    {item.item}
                  </Typography>
                  <Typography variant="h5" sx={{ color: '#239F7D', fontWeight: 'bold', mt: 1 }}>
                    {item.cost}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Why Burial Insurance Matters
          </Typography>
          <Typography variant="body1" paragraph>
            Without proper planning, your family could face financial hardship covering these expenses. Burial insurance ensures that funds are available when needed most, allowing your family to focus on grieving rather than worrying about costs.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Protect Your Family Today
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default AverageFuneralCost;
