import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const AffordableLifeInsuranceForSeniors = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Affordable Life Insurance for Seniors
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Quality coverage at prices you can afford
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Why Seniors Need Affordable Insurance
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            Fixed incomes, healthcare expenses, and rising costs make it challenging for seniors to afford traditional life insurance. That's why we've designed burial insurance specifically for seniors—providing essential coverage at prices that fit your budget.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Our Senior-Friendly Features
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Low Monthly Rates', desc: 'Starting from just $20-50/month' },
            { title: 'No Medical Exam', desc: 'Apply without extensive health screening' },
            { title: 'Flexible Coverage', desc: 'Choose coverage amount that fits your budget' },
            { title: 'Easy Approval', desc: 'Approved in 24 hours or less' },
            { title: 'Fixed Rates', desc: 'Rates never increase, guaranteed' },
            { title: 'Guaranteed Options', desc: 'Acceptance available regardless of health' }
          ].map((feature, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {feature.title}
                  </Typography>
                  <Typography variant="body2">{feature.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Real Example: Senior Protection Plan
          </Typography>
          <Stack spacing={2}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Age:</strong></Typography>
              <Typography>72</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Coverage Amount:</strong></Typography>
              <Typography>$15,000</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Monthly Cost:</strong></Typography>
              <Typography sx={{ fontWeight: 'bold', color: '#239F7D' }}>$45/month</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Type:</strong></Typography>
              <Typography>Guaranteed Acceptance</Typography>
            </Box>
          </Stack>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Affordable Coverage Today
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default AffordableLifeInsuranceForSeniors;
