import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const PrepaidBurialPlans = () => {
  const planFeatures = [
    { title: 'Locked-in Prices', desc: 'Prices are guaranteed and never increase' },
    { title: 'Peace of Mind', desc: 'Your family won\'t have to make arrangements' },
    { title: 'Payment Plans', desc: 'Flexible payment options available' },
    { title: 'Transferable', desc: 'Plans can be transferred if you move' }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Prepaid Burial Plans
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Lock in today's prices, protect your family tomorrow
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            What is a Prepaid Burial Plan?
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            A prepaid burial plan is a contract with a funeral home where you arrange and pay for your funeral services in advance. This ensures your funeral is exactly what you want and protects your family from unexpected costs.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Key Benefits
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {planFeatures.map((feature, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ textAlign: 'center', p: 3 }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 2 }}>
                  {feature.title}
                </Typography>
                <Typography variant="body2">{feature.desc}</Typography>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Prepaid vs. Burial Insurance
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>Prepaid Plans:</strong> You contract directly with a funeral home and prepay for services.
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>Burial Insurance:</strong> You purchase insurance that provides funds to cover funeral costs of your choice.
          </Typography>
          <Typography variant="body1">
            Many people choose to use burial insurance to fund a prepaid plan, giving them the best of both worlds.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Explore Prepaid Plans
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default PrepaidBurialPlans;
