import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const TypesOfBurialInsurance = () => {
  const types = [
    {
      title: 'Simplified Issue Life Insurance',
      description: 'Approved in minutes with minimal underwriting. Answers a few health questions.',
      coverage: 'Up to $50,000',
      path: '/burial-insurance/simplified-issue'
    },
    {
      title: 'Guaranteed Life Insurance',
      description: 'Guaranteed acceptance for eligible applicants. No medical questions asked.',
      coverage: 'Up to $25,000',
      path: '/burial-insurance/guaranteed'
    }
  ];

  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Types of Burial Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Find the right coverage option for your needs
          </Typography>
        </Container>
      </Box>

      {/* Types Grid */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          {types.map((type, idx) => (
            <Grid item xs={12} md={6} key={idx}>
              <Card sx={{ boxShadow: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
                <CardContent sx={{ p: 4, flexGrow: 1 }}>
                  <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 2, color: '#0170B9' }}>
                    {type.title}
                  </Typography>
                  <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', mb: 3 }}>
                    {type.description}
                  </Typography>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 3 }}>
                    Coverage: {type.coverage}
                  </Typography>
                  <Button
                    variant="contained"
                    fullWidth
                    sx={{
                      backgroundColor: '#FCDC00',
                      color: '#000',
                      fontWeight: 'bold',
                      '&:hover': { backgroundColor: '#E6C800' },
                    }}
                  >
                    Learn More
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3 }}>
            Not Sure Which Type is Right for You?
          </Typography>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#0170B9',
              color: '#FFFFFF',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Expert Guidance
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default TypesOfBurialInsurance;
