import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const FloridaFinalExpense = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Final Expense Insurance in Florida
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Florida-specific burial insurance information and costs
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Average Funeral Costs in Florida
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $9,000 - $13,000
                </Typography>
                <Typography variant="body1" paragraph>
                  Florida's average funeral costs are slightly above the national average due to higher service costs in popular retirement communities.
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Recommended Coverage
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $15,000 - $25,000
                </Typography>
                <Typography variant="body1" paragraph>
                  With average costs rising, we recommend coverage in this range for complete peace of mind.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Florida Cremation Laws
          </Typography>
          <Typography variant="body1" paragraph>
            Florida allows cremation with minimal restrictions. Cremation services in Florida average $2,000-$4,000, making it a more affordable option than traditional burial.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Florida Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default FloridaFinalExpense;
