import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const CremationCosts = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Cremation Costs
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            An affordable alternative to traditional burial
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3, height: '100%' }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Cremation Price Range
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $1,000 - $3,000
                </Typography>
                <Typography variant="body1" paragraph>
                  Direct cremation is typically the most affordable option, costing significantly less than traditional burial services.
                </Typography>

                <Typography variant="h6" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#0170B9' }}>
                  What's Typically Included:
                </Typography>
                <Stack spacing={1}>
                  {[
                    'Transportation of remains',
                    'Cremation process',
                    'Basic container or casket rental',
                    'Documentation and permits',
                    'Return of ashes'
                  ].map((item, idx) => (
                    <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00' }}>✓</Box>
                      <Typography>{item}</Typography>
                    </Box>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3, height: '100%' }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Cremation with Service
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $2,000 - $5,000
                </Typography>
                <Typography variant="body1" paragraph>
                  If you want a memorial service, reception, or other additions, costs will increase accordingly.
                </Typography>

                <Typography variant="h6" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#0170B9' }}>
                  Additional Costs May Include:
                </Typography>
                <Stack spacing={1}>
                  {[
                    'Memorial or celebration of life service',
                    'Reception or reception hall',
                    'Urn selection',
                    'Viewing arrangement',
                    'Flowers and decorations'
                  ].map((item, idx) => (
                    <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00' }}>✓</Box>
                      <Typography>{item}</Typography>
                    </Box>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Why Many Choose Cremation
          </Typography>
          <Typography variant="body1" paragraph>
            Cremation is increasingly popular as a cost-effective, flexible alternative to traditional burial. It allows families to hold services at their own pace and location, and eliminates ongoing cemetery maintenance costs.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get Protection Today
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default CremationCosts;
