import React from 'react';
import {
  Box,
  Container,
  Grid,
  Typography,
  Button,
  Link,
  Stack,
} from '@mui/material';
import PhoneIcon from '@mui/icons-material/Phone';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import EmailIcon from '@mui/icons-material/Email';
import FacebookIcon from '@mui/icons-material/Facebook';
import TwitterIcon from '@mui/icons-material/Twitter';
import LinkedInIcon from '@mui/icons-material/LinkedIn';

const Footer = () => {
  return (
    <Box
      component="footer"
      sx={{
        backgroundColor: '#3A3A3A',
        color: '#FFFFFF',
        py: 6,
        mt: 8,
      }}
    >
      <Container maxWidth="lg">
        <Grid container spacing={4}>
          {/* Company Info */}
          <Grid item xs={12} sm={6} md={3}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
              <Box
                sx={{
                  width: 40,
                  height: 40,
                  borderRadius: '50%',
                  backgroundColor: '#239F7D',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#FFFFFF',
                  fontWeight: 'bold',
                }}
              >
                AS
              </Box>
              <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                Aethon Services 
              </Typography>
            </Box>
            <Typography variant="body2" sx={{ color: '#DCDDDE', mb: 2 }}>
              Providing affordable and quick burial insurance for everyone.
            </Typography>
            <Stack direction="row" spacing={1}>
              <Link href="#" sx={{ color: '#FCDC00', '&:hover': { color: '#FFF' } }}>
                <FacebookIcon />
              </Link>
              <Link href="#" sx={{ color: '#FCDC00', '&:hover': { color: '#FFF' } }}>
                <TwitterIcon />
              </Link>
              <Link href="#" sx={{ color: '#FCDC00', '&:hover': { color: '#FFF' } }}>
                <LinkedInIcon />
              </Link>
            </Stack>
          </Grid>

          {/* Quick Links */}
          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2 }}>
              Quick Links
            </Typography>
            <Stack spacing={1}>
              <Link href="/" sx={{ color: '#DCDDDE', '&:hover': { color: '#FFF' } }}>
                Home
              </Link>
              <Link href="/burial-insurance" sx={{ color: '#DCDDDE', '&:hover': { color: '#FFF' } }}>
                Burial Insurance
              </Link>
              <Link href="/about" sx={{ color: '#DCDDDE', '&:hover': { color: '#FFF' } }}>
                About Us
              </Link>
              <Link href="/contact" sx={{ color: '#DCDDDE', '&:hover': { color: '#FFF' } }}>
                Contact
              </Link>
            </Stack>
          </Grid>

          {/* Contact Info */}
          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2 }}>
              Contact Info
            </Typography>
            <Stack spacing={2}>
              <Stack direction="row" spacing={1} alignItems="flex-start">
                <PhoneIcon sx={{ color: '#FCDC00', mt: 0.5 }} />
                <Box>
                  <Typography variant="body2" sx={{ color: '#DCDDDE' }}>
                    Phone
                  </Typography>
                  <Link href="tel:+18882415309" sx={{ color: '#FFFFFF', '&:hover': { color: '#FFF' } }}>
                    +18882415309
                  </Link>
                </Box>
              </Stack>
              <Stack direction="row" spacing={1} alignItems="flex-start">
                <LocationOnIcon sx={{ color: '#FCDC00', mt: 0.5 }} />
                <Box>
                  <Typography variant="body2" sx={{ color: '#DCDDDE' }}>
                    Address
                  </Typography>
                  <Typography sx={{ color: '#FFFFFF', fontSize: '0.9rem' }}>
                    85 Rose Ct, Albany NY 12209
                  </Typography>
                </Box>
              </Stack>
              <Stack direction="row" spacing={1} alignItems="flex-start">
                <EmailIcon sx={{ color: '#FCDC00', mt: 0.5 }} />
                <Box>
                  <Typography variant="body2" sx={{ color: '#DCDDDE' }}>
                    Email
                  </Typography>
                  <Link href="mailto:Aethonservicesus@gmail.com" sx={{ color: '#FFFFFF', '&:hover': { color: '#FFF' } }}>
                    Aethonservicesus@gmail.com
                  </Link>
                </Box>
              </Stack>
            </Stack>
          </Grid>

          {/* Newsletter
          <Grid item xs={12} sm={6} md={3}>
            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 2 }}>
              Newsletter
            </Typography>
            <Typography variant="body2" sx={{ color: '#DCDDDE', mb: 2 }}>
              Subscribe to get updates and special offers.
            </Typography>
            <Stack direction="row" spacing={1}>
              <input
                type="email"
                placeholder="Your email"
                style={{
                  flex: 1,
                  padding: '10px 15px',
                  borderRadius: '5px',
                  border: 'none',
                  fontSize: '0.9rem',
                }}
              />
              <Button
                variant="contained"
                sx={{
                  backgroundColor: '#FCDC00',
                  color: '#000',
                  '&:hover': {
                    backgroundColor: '#E6C800',
                  },
                }}
              >
                Subscribe
              </Button>
            </Stack>
          </Grid> */}
        </Grid>

        {/* Bottom Bar */}
        <Box
          sx={{
            borderTop: '1px solid #555d66',
            mt: 4,
            pt: 3,
            display: 'flex',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: 2,
          }}
        >
          <Typography variant="body2" sx={{ color: '#DCDDDE' }}>
            &copy; 2024 Senior Life Services. All rights reserved.
          </Typography>
          <Stack direction="row" spacing={2}>
            <Link href="#" sx={{ color: '#DCDDDE', fontSize: '0.9rem', '&:hover': { color: '#FFF' } }}>
              Privacy Policy
            </Link>
            <Link href="#" sx={{ color: '#DCDDDE', fontSize: '0.9rem', '&:hover': { color: '#FFF' } }}>
              Terms of Service
            </Link>
          </Stack>
        </Box>
      </Container>
    </Box>
  );
};

export default Footer;
