import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const AlaskaFinalExpense = () => {
  return (
    <Box sx={{ width: '100%' }}>
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Final Expense Insurance in Alaska
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Affordable final expense coverage for Alaska residents
          </Typography>
        </Container>
      </Box>

      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Final Expense Insurance for Alaska Residents
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Final expense insurance helps cover the costs of funeral and burial services in Alaska. With coverage options starting at just a few dollars per month, you can protect your family from unexpected expenses.
                </Typography>
                
                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Why Choose Final Expense Insurance?
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1rem', lineHeight: 1.8 }}>
                  • No medical exam required
                  • Guaranteed acceptance
                  • Fixed rates that never increase
                  • Coverage up to $50,000
                  • Quick approval process
                  • Tax-free benefits for your family
                </Typography>

                <Button
                  variant="contained"
                  sx={{
                    backgroundColor: '#FCDC00',
                    color: '#000',
                    mt: 3,
                    py: 1.5,
                    px: 3,
                    '&:hover': { backgroundColor: '#E6C800' },
                  }}
                >
                  Get Your Quote Today
                </Button>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default AlaskaFinalExpense;
