import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const BurialInsuranceForCancer = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Burial Insurance for Cancer Patients
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Coverage available regardless of diagnosis
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            We Cover Cancer Patients
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            Being diagnosed with cancer shouldn't exclude you from insurance coverage. We work with carriers that specialize in insuring cancer survivors and those currently undergoing treatment.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          Coverage Options for Cancer Patients
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Guaranteed Acceptance', desc: 'Available to most cancer patients regardless of stage' },
            { title: 'No Medical Exam', desc: 'Simple application process without lab work' },
            { title: 'Quick Approval', desc: 'Coverage in 24 hours' },
            { title: 'Flexible Coverage', desc: 'Choose the amount that fits your situation' }
          ].map((option, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {option.title}
                  </Typography>
                  <Typography variant="body2">{option.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            What You Can Expect
          </Typography>
          <Stack spacing={2}>
            {[
              'Easy application with health questions',
              'No need to report current treatment',
              'Fixed rates for life of policy',
              'Peace of mind for your family',
              'Quick, compassionate service'
            ].map((item, idx) => (
              <Box key={idx} sx={{ display: 'flex', gap: 2 }}>
                <Box sx={{ color: '#FCDC00' }}>✓</Box>
                <Typography>{item}</Typography>
              </Box>
            ))}
          </Stack>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Apply Now
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default BurialInsuranceForCancer;
