import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button } from '@mui/material';

const CaliforniaFinalExpense = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Final Expense Insurance in California
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            California-specific burial insurance information and costs
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Average Funeral Costs in California
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $11,000 - $15,000
                </Typography>
                <Typography variant="body1" paragraph>
                  California has some of the highest funeral costs in the nation, particularly in the Bay Area and Los Angeles regions.
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Recommended Coverage
                </Typography>
                <Typography variant="h3" sx={{ fontWeight: 'bold', color: '#239F7D', mb: 2 }}>
                  $20,000 - $35,000
                </Typography>
                <Typography variant="body1" paragraph>
                  Due to higher costs, California residents should consider higher coverage amounts.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4, mt: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            California Cremation Laws
          </Typography>
          <Typography variant="body1" paragraph>
            California is one of the most cremation-friendly states, with straightforward regulations. Cremation costs range from $2,500-$4,000 and provide an affordable alternative to traditional burial.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Get California Quote
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default CaliforniaFinalExpense;
