import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const GuaranteedLifeInsurance = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Guaranteed Life Insurance
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            Guaranteed acceptance for eligible applicants
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Grid container spacing={4}>
          <Grid item xs={12}>
            <Card sx={{ boxShadow: 3 }}>
              <CardContent sx={{ p: 4 }}>
                <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
                  Guaranteed Acceptance Coverage
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Guaranteed life insurance provides coverage to those who might not qualify for other insurance products. With no medical questions and guaranteed acceptance, you can rest assured your family will be protected.
                </Typography>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Key Advantages:
                </Typography>
                <Stack spacing={2} sx={{ mb: 4 }}>
                  {[
                    'Guaranteed acceptance - no health questions',
                    'No medical exam required',
                    'Coverage up to $25,000',
                    'Fixed rates for life',
                    'Quick processing',
                    'Covers pre-existing conditions',
                    'No waiting period for accidental death'
                  ].map((advantage, idx) => (
                    <Box key={idx} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                      <Box sx={{ color: '#FCDC00', fontSize: '1.5rem' }}>✓</Box>
                      <Typography>{advantage}</Typography>
                    </Box>
                  ))}
                </Stack>

                <Typography variant="h5" sx={{ fontWeight: 'bold', mt: 4, mb: 2, color: '#239F7D' }}>
                  Perfect For:
                </Typography>
                <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
                  Those with serious health conditions, high-risk situations, or anyone who wants the peace of mind knowing they're automatically approved. Our guaranteed policies have helped thousands of families protect their loved ones.
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Apply with Guaranteed Acceptance
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default GuaranteedLifeInsurance;
