import React from 'react';
import { Box, Container, Typography, Grid, Card, CardContent, Button, Stack } from '@mui/material';

const LifeInsuranceForSeniorsOver80 = () => {
  return (
    <Box sx={{ width: '100%' }}>
      {/* Hero Section */}
      <Box
        sx={{
          background: 'linear-gradient(135deg, #0170B9 0%, #239F7D 100%)',
          color: '#FFFFFF',
          py: 8,
          textAlign: 'center',
        }}
      >
        <Container>
          <Typography variant="h1" sx={{ fontWeight: 'bold', mb: 2 }}>
            Life Insurance for Seniors Over 80
          </Typography>
          <Typography variant="h5" sx={{ fontWeight: 300 }}>
            It's never too late to get coverage
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container sx={{ py: 6 }}>
        <Card sx={{ boxShadow: 3, mb: 4, p: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Age 80 and Beyond - We Have Options
          </Typography>
          <Typography variant="body1" paragraph sx={{ fontSize: '1.1rem', lineHeight: 1.8 }}>
            Turning 80 doesn't mean you can't get life insurance. While options may be more limited, we specialize in helping seniors over 80 find burial insurance coverage to protect their families.
          </Typography>
        </Card>

        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 4, textAlign: 'center' }}>
          What Makes This Different
        </Typography>

        <Grid container spacing={3} sx={{ mb: 4 }}>
          {[
            { title: 'Guaranteed Options', desc: 'Acceptance available for ages 80-95' },
            { title: 'Lower Coverage', desc: 'Typically $5,000-$25,000 range' },
            { title: 'Higher Rates', desc: 'Premium costs reflect age and health' },
            { title: 'Quick Approval', desc: 'Simplified process for immediate coverage' }
          ].map((item, idx) => (
            <Grid item xs={12} sm={6} key={idx}>
              <Card sx={{ boxShadow: 2 }}>
                <CardContent sx={{ p: 3 }}>
                  <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0170B9', mb: 1 }}>
                    {item.title}
                  </Typography>
                  <Typography variant="body2">{item.desc}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Card sx={{ boxShadow: 3, p: 4 }}>
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3, color: '#0170B9' }}>
            Sample Rates for Ages 80+
          </Typography>
          <Stack spacing={2}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', pb: 1, borderBottom: '1px solid #E5E5E5' }}>
              <Typography><strong>Age 80-85</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$75-150/month</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', pb: 1, borderBottom: '1px solid #E5E5E5' }}>
              <Typography><strong>Age 85-90</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$150-250/month</Typography>
            </Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography><strong>Age 90+</strong></Typography>
              <Typography sx={{ color: '#239F7D' }}>$250+/month</Typography>
            </Box>
          </Stack>
          <Typography variant="body2" sx={{ mt: 2, color: '#7A7A7A' }}>
            * Rates vary based on health and coverage amount. Contact us for your specific quote.
          </Typography>
        </Card>

        {/* CTA */}
        <Box sx={{ textAlign: 'center', mt: 8 }}>
          <Button
            variant="contained"
            size="large"
            sx={{
              backgroundColor: '#FCDC00',
              color: '#000',
              fontWeight: 'bold',
              padding: '12px 40px',
            }}
          >
            Apply Today
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default LifeInsuranceForSeniorsOver80;
